catalogo.mrc: os registos em MARC 21 com os exemplares no campo 952. Carrega-se em «Ferramentas > Preparar registos MARC para importação» e, ao importar, indica-se para adicionar os exemplares.

lectores.csv: os leitores, na «Importação de utilizadores» do Koha, com o seu cartão. Antes é necessário criar no Koha a biblioteca (o código da coluna branchcode, também em $a e $b de cada 952) e as categorias ST, T, S e PT; e os tipos de exemplar BK e REF.

prestamos.koc: os livros que estão fora, em «Circulação > Carregar ficheiro de circulação offline». Fica para o fim, com os leitores e os exemplares já dentro.';
$string['copymade'] = 'Cópia feita.';
$string['copymake'] = 'Fazer uma cópia agora';
$string['copyreadme'] = 'Cópia das bibliotecas de {$a->entity}, feita a {$a->date} por Oksigenia Ayvurenda {$a->release}.

Cada ficheiro CSV é uma tabela, com os nomes das colunas na primeira linha. Abrem-se com qualquer folha de cálculo.

- entity, library: a entidade e as suas bibliotecas.
- record, authority, recauth: o catálogo (títulos, autores, assuntos…).
- item: os exemplares e o material, com os seus códigos.
- reader, member: os leitores e a sua turma de cada ano letivo.
- loan: os empréstimos, em curso e devolvidos.
- hold: as reservas, em fila, separadas e concluídas.
- stocktake, stockread: os inventários e o que foi lido em cada um.
- withdrawal, withdrawn: os autos de abate e os seus exemplares.
- lot, lotitem: os lotes entre bibliotecas e os seus exemplares.
- digital: as formas digitais dos registos (sem os seus ficheiros, que ficam no sítio).
- rule, year, tutor, source: regras de empréstimo, anos letivos, diretores de turma e de onde veio cada linha.
- catalogo.mrc e catalogo.xml: o catálogo em MARC21 (ISO 2709 e MARCXML), com os seus exemplares no campo 852, para levar para qualquer programa de biblioteca.
- catalogo-dc.xml: o catálogo em Dublin Core, para repositórios e catálogos que não leem MARC.
- catalogo.ris: o catálogo em RIS, para gestores de referências como o Zotero ou o Mendeley.
- challenge, wish: os desafios das turmas e o que pediram.
- review, roomread: as opiniões e o que foi lido na sala.
- bankset, banktitle: os lotes do banco de manuais escolares e os seus títulos.
- koha/: o mesmo, preparado para levar para o Koha (vê o seu LEIAME).

As capas e o fundo digital vão noutra cópia, a dos ficheiros. As vozes gravadas não saem do servidor.

Linhas de cada ficheiro:
{$a->counts}
