$string['helpbank01'] = 'Um lote é o que se empresta a cada aluno de certas turmas: os seus títulos e a que turmas se destina.';
$string['helpbank02'] = 'Cada título indica quantos exemplares estão emprestados e quantos estão disponíveis; se não chegarem para todos, avisa a vermelho.';
$string['helpbank03'] = 'Para adicionar um título ao lote, procura-o pelo seu nome ou ISBN.';
$string['helpbank04'] = 'Um lote novo: o seu nome e as turmas a que se destina. Cada aluno dessas turmas fica a aguardar todos os seus títulos.';
$string['helpbank05'] = 'Por turmas: cada turma, com quem espera livros e quem os tem.';
$string['helpbank06'] = 'Numa turma, cada aluno com o que tem e o que lhe falta. No balcão, o seu lote surge ao passar o seu cartão, com o contrato para a família.';
$string['helpbankround01'] = 'Aqui faz-se a recolha de final de ano letivo: quantos livros faltam devolver e quantos já voltaram.';
$string['helpbankround02'] = 'Define a data-limite. Os avisos vão indicá-la.';
$string['helpbankround03'] = 'Com um clique, cada leitor recebe um aviso com os seus livros, e cada diretor de turma, quem da sua turma os tem. No máximo, uma vez por dia.';
$string['helpbankround04'] = 'Cada turma, com o que tem emprestado. Entra numa para ver quem tem o quê.';
$string['helpbankround05'] = 'Se um livro não voltar, regista-se como perdido. O banco não cobra nada: indica o que falta e de quem.';
$string['helpbankround06'] = 'Se aparecer, com um clique volta para a estante.';
$string['helpbankround07'] = 'E ao começar o ano letivo, a distribuição: quem espera livros e quantos exemplares faltam em cada lote.';
$string['helpbankround08'] = 'Cada turma tem a sua lista e os seus contratos, para imprimir e para as famílias assinarem.';
$string['helpcard01'] = 'Este é o cartão de um leitor, tal como ele o vê: no telemóvel, na sala de aula ou no computador da biblioteca.';
$string['helpcard02'] = 'A sua flor cresce com o que acontece no balcão: voltar, explorar novos cantinhos, partilhar o que achou de um livro e terminar o que começa. Nunca murcha.';
$string['helpcard03'] = 'O código do cartão passa pelo balcão como um livro: com a pistola, com a câmara ou com o telemóvel.';
$string['helpcard04'] = 'Aqui vê por que caminhos cresce, sem números nem comparações com ninguém.';
$string['helpcard05'] = 'A partir dos doze anos aparece o céu em vez da flor, e cada um pode escolher o aspeto clássico. Tu podes vê-lo como ele o veria.';
$string['helpcard06'] = 'É assim que um leitor do 3.º ciclo o vê: o mesmo cartão, com outro aspeto.';
$string['helpcard07'] = 'Para os imprimir, «Imprimir cartões» em Leitores: de toda a instituição, de um ciclo ou de uma turma, cada um com o seu modelo.';
$string['helpcardprint01'] = 'Primeiro, de quem: todos os leitores ou uma parte. Um leitor individual imprime-se a partir do seu registo.';
$string['helpcardprint02'] = 'O modelo de cada cartão, consoante a idade de quem o tem. «Alterar» define um para todos ou um diferente por idades.';
$string['helpcardprint03'] = 'O logótipo aparece em cima, à direita, em cada cartão.';
$string['helpcardprint04'] = 'Onde são impressos: numa gráfica, em cartões de plástico, em folhas de cartões ou em papel normal. Cada forma prepara o PDF à sua medida.';
$string['helpcardprint05'] = 'O que diz o verso: a morada e umas linhas da biblioteca, igual em todos.';
$string['helpcardprint06'] = 'E «Preparar». Se forem poucos, descarregam-se no momento; se forem muitos, preparam-se à parte e aparecem em «Preparados».';
$string['helpdesk01'] = 'Isto é o balcão: um único campo, sempre pronto. O leitor de códigos escreve nele sozinho, e também se pode escrever à mão.';
$string['helpdesk02'] = 'Chega a Ana com um livro. Primeiro, o seu cartão.';
$string['helpdesk03'] = 'Abre-se o seu registo: o que tem em casa e se algo está em atraso.';
$string['helpdesk04'] = 'Agora o livro. Fica emprestado, com a sua data de devolução, e soa um toque curto.';
$string['helpdesk05'] = 'Se te enganaste, «Desfazer» deixa-o como estava.';
