$string['helpintroreports'] = 'Um minuto com os seis relatórios da biblioteca, sobre os empréstimos inventados da biblioteca de treino.';
$string['helpintroreviews'] = 'Um minuto para publicar opiniões, com duas inventadas da biblioteca de treino.';
